/* Capa de RELATÓRIO DE TECNOLOGIA — os elementos da capa que o time já usa.
 *
 * Os selos e a assinatura saem do PDF COM A TRANSPARÊNCIA APLICADA. Ela mora num
 * SMask, um objeto separado: extrair só a imagem trazia o fundo preto junto (o
 * retângulo que apareceu na primeira capa), e recortar da página renderizada
 * trazia o fundo escuro — que quase combina com o do slide, mas não exatamente,
 * e o "quase" vira um retângulo visível. Com o alfa aplicado e a moldura vazia
 * cortada, só as formas são desenhadas e não há o que combinar.
 *
 * As proporções são as da própria imagem (selos 1,98; assinatura 2,69), e as
 * caixas no slide seguem elas — forçar um quadrado esticava os selos.
 *
 * Ficam em arquivo separado, e não dentro de apresentacao.js: é base64 que
 * ninguém precisa reler ao mexer na lógica dos slides, e o navegador guarda este
 * arquivo em cache entre as gerações.
 */
window.CAPA_TECNOLOGIA = {
  fundo: 'data:image/jpeg;base64,',
  selos: 'data:image/png;base64,',
  logo: 'data:image/png;base64,',
  // Posição e tamanho em polegadas, convertidos da capa original (960x540pt,
  // divisor 96) e medidos na página renderizada.
  selosPos: { x: 8.58, y: 0.40, w: 0.94, h: 0.475 },
  logoPos:  { x: 8.13, y: 4.83, w: 1.41, h: 0.524 },
  verde: '00FD54',
};
